"""Shared native spacing policy for original-path corridors and patch charts.

This is a construction operation on local shared node groups. It adds no
per-fixture solver, Python evaluation handler or authored input geometry.
Existing height/projection/placement guards remain after the corrected chart.
Complete network and editing qualification belongs to the generated asset.
"""
from .path_surface_nodes import _Nodes
from . import curved_quad_strip_refinement_nodes as refinement
from . import curved_quad_fair_nodes as quality
from . import quad_spacing_nodes as spacing

VERSION = 1
SOURCE_KEYS = ('st_contact_choice_source', 'st_complete_constructor_source')
POLICY = dict(version=VERSION, quality_trigger=8., maximum_divisions=2,
              propagation_steps=4, spacing_steps=32, target_ratio=7.5,
              stop_ratio=7.75, target_sine=.25, pin_attribute='st_cq_fixed',
              short_corridors='matching denser mouths; span <= width; preserve source knots')


def reachable(entries):
    if hasattr(entries, 'nodes'): entries = (entries,)
    pending = list(entries); seen = set()
    while pending:
        tree = pending.pop()
        if tree in seen: continue
        seen.add(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
        pending.extend(tree[key] for key in SOURCE_KEYS if tree.get(key) is not None)
    return seen


def short_corridors(trees):
    """Keep dense matching entrance counts across short source intervals."""
    changes = []
    for tree in sorted(trees, key=lambda item:item.name):
        if not tree.name.startswith('Prochitecture Streets / Original corridor density chart v2'):
            continue
        if tree.library: raise ValueError('Modify only a local export or trial copy')
        if tree.get('st_short_corridor_density'): raise ValueError('Short corridor policy already installed')
        records = [node for node in tree.nodes if node.bl_idname == 'GeometryNodeStoreNamedAttribute'
                   and node.inputs['Name'].default_value == 'st_cr_base_count']
        inputs = [node for node in tree.nodes if node.type == 'GROUP_INPUT']
        if len(records) != 1 or len(inputs) != 1 or len(records[0].inputs['Value'].links) != 1:
            raise ValueError('Unrecognized corridor density implementation: '+tree.name)
        base = records[0].inputs['Value'].links[0].from_socket
        consumers = [link.to_socket for link in tuple(base.links)]
        g = _Nodes(tree); inp = inputs[0]
        bands = g.math('SUBTRACT', 2., g.math('ABSOLUTE', inp.outputs['Half']))
        ca = g.math('DIVIDE', inp.outputs['Start Intervals'], bands)
        cb = g.math('DIVIDE', inp.outputs['End Intervals'], bands)
        span = g.math('SUBTRACT', inp.outputs['End'], inp.outputs['Start'])
        retain = g.all(g.compare(ca, cb), g.compare(ca, base, 'GREATER_THAN'),
                       g.compare(span, inp.outputs['Width'], 'LESS_EQUAL'))
        selected = g.switch(retain, base, ca)
        for socket in consumers: g.set(selected, socket)
        tree['st_short_corridor_density'] = VERSION
        tree['st_short_corridor_density_policy'] = POLICY['short_corridors']
        changes.append(dict(group=tree.name, old_consumers=len(consumers)))
    if not changes: raise ValueError('No saved corridor density chart found')
    return changes


def patch_charts(entries):
    """Repair proportions before inverse/forward heights, preserving pins."""
    changes = []; c = refinement.c
    for tree in sorted(reachable(entries), key=lambda item:item.name):
        calls = [node for node in tuple(tree.nodes) if node.type == 'GROUP' and node.node_tree]
        targets = []
        for call in calls:
            target = call.node_tree
            inverse = (target.name.startswith('Prochitecture Streets / Curved patch bounded height v2')
                       and 'Cyclic mouths' in target.name)
            forward = target.get('st_height_method') == 'forward_regular_corner_v1'
            if inverse or forward: targets.append((call, forward))
        if not targets: continue
        if tree.library: raise ValueError('Modify only a local export or trial copy')
        if tree.get('st_preheight_density_policy') or tree.get('st_preheight_density_trial'):
            raise ValueError('Pre-height density policy already installed: '+tree.name)
        for call, forward in targets:
            assert all(key in call.inputs for key in ('Geometry', 'Mouths', 'Input Valid', 'Height Exaggeration'))
            assert all(key in call.outputs for key in ('Geometry', 'Projection Valid', 'Bounds Valid', 'Charts Agree'))
            source, = [link.from_socket for link in call.inputs['Geometry'].links]
            g = c.Graph.__new__(c.Graph); g.g = tree; g.count = len(tree.nodes); g.frame = None
            metric = g.node('GeometryNodeGroup', 'Read XY proportions before bounded patch heights')
            metric.node_tree = quality.build(steps=0); g.bind(source, metric.inputs['Geometry'])
            refine = g.node('GeometryNodeGroup', 'Bounded directional quads; complete entrances preserved')
            refine.node_tree = refinement.build_shared(iterations=4, maximum=2, profile_records=True)
            g.bind(source, refine.inputs['Geometry'])
            residual = g.node('GeometryNodeGroup', 'Read remaining proportions after entrance-locked strips')
            residual.node_tree = metric.node_tree; g.bind(refine.outputs['Geometry'], residual.inputs['Geometry'])
            adjust = g.node('GeometryNodeGroup', 'Bounded interior correction with exact source and curb pins')
            adjust.node_tree = spacing.build(steps=32, target_ratio=7.5, target_sine=.25,
                                            stop_ratio=7.75, pin_attribute='st_cq_fixed')
            planar = c._store(g, refine.outputs['Geometry'], 'st_cn_height', 0., 'FLOAT')
            g.bind(planar, adjust.inputs['Geometry'])
            corrected = c.choose(g, g.math('GREATER_THAN', residual.outputs['Maximum Edge Ratio'], 8.),
                                 adjust.outputs['Geometry'], refine.outputs['Geometry'], 'GEOMETRY')
            needed = g.math('GREATER_THAN', metric.outputs['Maximum Edge Ratio'], 8.)
            g.bind(c.choose(g, needed, corrected, source, 'GEOMETRY'), call.inputs['Geometry'])
            changes.append(dict(parent=tree.name, height=call.node_tree.name,
                                coordinates='forward' if forward else 'inverse'))
        tree['st_preheight_density_policy'] = VERSION
    if not changes: raise ValueError('No original bounded patch-height calls found')
    return changes


def install(entries):
    """Apply the policy once to all runtime and deferred builder entry paths."""
    graph = reachable(entries)
    corridors = short_corridors(graph)
    patches = patch_charts(entries)
    return dict(policy=dict(POLICY), corridors=corridors, patches=patches)
